# Domain Classification Engine - runnable demo (JAH-ATK173-000001)
RANK = 1
SIG = False
DOCS = ['The telescope tracked the planet across the night sky.', 'Bake the flour and sugar in a hot oven.', 'The patient received a second vaccine dose.']
GAZ = {"astronomy": ["telescope", "stars", "planet", "orbit", "galaxy"],
       "cooking": ["recipe", "flour", "oven", "bake", "sugar"],
       "medicine": ["vaccine", "dose", "patient", "diagnosis", "treatment"]}
for d in DOCS:
    words = set(d.lower().split())
    scores = {dom: len(words & set(terms)) for dom, terms in GAZ.items()}
    best = max(scores, key=scores.get)
    conf = scores[best] / max(1, sum(scores.values()))
    label = best if scores[best] > 0 else "unclassified"
    print("%-8s (conf %.2f) <- %s" % (label, conf, d[:50]))
    if RANK >= 2: print("   scores:", scores)
if RANK >= 3:
    print("domains covered:", len(GAZ))
if SIG:
    print("Signature lineage stamp: JAH-SIG-DOM-" + "JAH-ATK173-000001")
print("record:", "JAH-ATK173-000001", "OK")

